params.command:
$ErrorActionPreference='Stop'
$repo=Join-Path $env:USERPROFILE 'local-ai-workspaces\mhw-mods'
$branch='integration/complete-mod-workflows-final-1142-a2'
$wt=Join-Path $env:USERPROFILE 'agent-worktrees\complete-workflows-final-1142-a2'
git -C $repo fetch origin --prune
$base=(git -C $repo rev-parse origin/main).Trim()
if(Test-Path $wt){throw ('WORKTREE_PATH_EXISTS:'+ $wt)}
git -C $repo worktree add -b $branch $wt origin/main
if($LASTEXITCODE -ne 0){throw 'WORKTREE_ADD_FAILED'}
Push-Location $wt
try {
  $savedPref=$ErrorActionPreference
  $ErrorActionPreference='Continue'
  git merge --no-commit --no-ff origin/codex/complete-mod-workflows
  $mergeExit=$LASTEXITCODE
  $ErrorActionPreference=$savedPref
  if($mergeExit -ne 0){Write-Output 'EXPECTED_MERGE_CONFLICTS'}

  # Canonical main wins for historical state, release identity, and CI.
  git restore --source=HEAD --staged --worktree -- .gitattributes .github/workflows/windows-workflows.yml .gitignore .verification AGENTS.md CHANGELOG.md README.md _AGENT_CONTEXT
  if($LASTEXITCODE -ne 0){throw 'RESTORE_CURRENT_STATE_FAILED'}

  # Keep current dashboard and add only the workflow entry point.
  git checkout --ours -- src/MhwModManager.App/MainWindow.xaml
  $xaml='src/MhwModManager.App/MainWindow.xaml'
  $x=[IO.File]::ReadAllText($xaml)
  if($x -notmatch 'OpenWorkflowsCommand'){
    $anchor='Content="Export collection recipe"'
    $i=$x.IndexOf($anchor,[StringComparison]::Ordinal)
    if($i -lt 0){throw 'WORKFLOW_BUTTON_ANCHOR_NOT_FOUND'}
    $e=$x.IndexOf([char]10,$i); if($e -lt 0){$e=$x.Length-1}
    $button='                                    <Button Margin="0,0,0,7" HorizontalContentAlignment="Left" Content="Loadouts, rules &amp; diagnostics" Command="{Binding OpenWorkflowsCommand}"/>'+[Environment]::NewLine
    $x=$x.Insert($e+1,$button)
    [IO.File]::WriteAllText($xaml,$x,[Text.UTF8Encoding]::new($false))
  }
  git add -- $xaml

  # Keep current modular VM and graft only crash-diagnosis correctness deltas.
  git checkout --ours -- src/MhwModManager.App/ViewModels/MainWindowViewModel.cs
  $vmPath='src/MhwModManager.App/ViewModels/MainWindowViewModel.cs'
  $vm=[IO.File]::ReadAllText($vmPath)
  $vm=$vm.Replace('if(result.Isolated)await s.Issues.MarkBisectResultAsync(result.Suspects,ct:ct);','if(result.Isolated && result.Suspects.Count == 1)await s.Issues.MarkBisectResultAsync(result.Suspects,ct:ct);')
  $vm=$vm.Replace('await ApplyStateDirectAsync(currentState,"Restore setup after crash diagnosis",ct);','await ApplyStateDirectAsync(currentState,"Restore setup after crash diagnosis",CancellationToken.None);')
  $oldProbe='var delay=Task.Delay(TimeSpan.FromSeconds(12),ct);var exit=process.WaitForExitAsync(ct);var completed=await Task.WhenAny(delay,exit);'+[Environment]::NewLine+'        if(completed==exit)return true;'+[Environment]::NewLine+'        try{process.Kill(true);await process.WaitForExitAsync(ct);}catch(InvalidOperationException){}'+[Environment]::NewLine+'        return false;'
  $newProbe='try'+[Environment]::NewLine+'        {'+[Environment]::NewLine+'            var delay=Task.Delay(TimeSpan.FromSeconds(12),ct);var exit=process.WaitForExitAsync(ct);'+[Environment]::NewLine+'            var completed=await Task.WhenAny(delay,exit);ct.ThrowIfCancellationRequested();'+[Environment]::NewLine+'            if(completed==exit){await exit;return true;}'+[Environment]::NewLine+'            return false;'+[Environment]::NewLine+'        }'+[Environment]::NewLine+'        finally'+[Environment]::NewLine+'        {'+[Environment]::NewLine+'            try{if(!process.HasExited){process.Kill(true);await process.WaitForExitAsync(CancellationToken.None);}}'+[Environment]::NewLine+'            catch(InvalidOperationException){}'+[Environment]::NewLine+'        }'
  if($vm.Contains($oldProbe)){$vm=$vm.Replace($oldProbe,$newProbe)}
  elseif($vm -notmatch 'WaitForExitAsync\(CancellationToken.None\)'){throw 'CRASH_PROBE_ANCHOR_NOT_FOUND'}
  [IO.File]::WriteAllText($vmPath,$vm,[Text.UTF8Encoding]::new($false))
  git add -- $vmPath

  # Legacy branch contains the richer ddmin implementation on top of baseline/full-set validation.
  git checkout --theirs -- src/MhwModManager.Automation/CrashBisectorEngine.cs
  git add -- src/MhwModManager.Automation/CrashBisectorEngine.cs

  # Preserve current safe traversal/extraction, add interactive-installer hold behavior.
  git checkout --ours -- src/MhwModManager.Automation/SmartInboxService.cs
  $inboxPath='src/MhwModManager.Automation/SmartInboxService.cs'
  $inbox=[IO.File]::ReadAllText($inboxPath)
  if($inbox -notmatch 'FomodInstallerService.HasInstaller'){
    $anchor='                var category = categories.Classify('
    $i=$inbox.IndexOf($anchor,[StringComparison]::Ordinal)
    if($i -lt 0){throw 'SMART_INBOX_ANCHOR_NOT_FOUND'}
    $block='                if (FomodInstallerService.HasInstaller(destination))'+[Environment]::NewLine+
      '                {'+[Environment]::NewLine+
      '                    Directory.Delete(destination, true);'+[Environment]::NewLine+
      '                    results.Add(new(entry, null, false, AutomationCategory.Unknown, "Installer choices required. Use Import and select this Inbox archive; source left untouched."));'+[Environment]::NewLine+
      '                    continue;'+[Environment]::NewLine+
      '                }'+[Environment]::NewLine
    $inbox=$inbox.Insert($i,$block)
    [IO.File]::WriteAllText($inboxPath,$inbox,[Text.UTF8Encoding]::new($false))
  }
  git add -- $inboxPath

  # Keep current self-test breadth, update recipe expectation to portable format v2.
  git checkout --ours -- tools/MhwModManager.SelfTest/Program.cs
  $selfPath='tools/MhwModManager.SelfTest/Program.cs'
  $self=[IO.File]::ReadAllText($selfPath)
  $oldRecipe='await Run("Recipe export",async()=>{var db=await Db("recipe.db");var path=Path.Combine(temp,"recipe.json");await new CollectionRecipeService(db).ExportAsync(path);using var doc=JsonDocument.Parse(await File.ReadAllTextAsync(path));if(doc.RootElement.GetProperty("format").GetInt32()!=1)throw new InvalidOperationException("Recipe format missing.");});'
  $newRecipe='await Run("Recipe export",async()=>{var db=await Db("recipe.db");var path=Path.Combine(temp,"recipe.json");await new CollectionRecipeService(db,GameProfile.MonsterHunterWorld(Path.Combine(temp,"game"))).ExportAsync(path);using var doc=JsonDocument.Parse(await File.ReadAllTextAsync(path));if(doc.RootElement.GetProperty("format").GetInt32()!=2)throw new InvalidOperationException("Recipe format 2 missing.");var preview=await new CollectionRecipeService(db,GameProfile.MonsterHunterWorld(Path.Combine(temp,"game"))).PreviewAsync(path);if(preview.Matches.Count!=0)throw new InvalidOperationException("Empty recipe round-trip was not empty.");});'
  if($self.Contains($oldRecipe)){$self=$self.Replace($oldRecipe,$newRecipe)}
  elseif($self -notmatch 'Recipe format 2'){throw 'SELFTEST_RECIPE_ANCHOR_NOT_FOUND'}
  [IO.File]::WriteAllText($selfPath,$self,[Text.UTF8Encoding]::new($false))
  git add -- $selfPath

  # Adapt FOMOD to current ArchiveImportService boundary instead of reviving the old monolithic VM import.
  $importerPath='src/MhwModManager.Automation/ArchiveImportService.cs'
  $imp=[IO.File]::ReadAllText($importerPath)
  $sig='    public async Task<ArchiveImportResult> ImportAsync(string archivePath, CancellationToken ct = default)'
  $replacement=@'
    public Task<ArchiveImportResult> ImportAsync(string archivePath, CancellationToken ct = default)
        => ImportCoreAsync(archivePath, null, null, ct);

    public Task<ArchiveImportResult> ImportAsync(
        string archivePath,
        GameProfile game,
        Func<FomodInstallerService, CancellationToken, Task<IReadOnlySet<string>?>> chooseFomod,
        CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(game);
        ArgumentNullException.ThrowIfNull(chooseFomod);
        return ImportCoreAsync(archivePath, game, chooseFomod, ct);
    }

    private async Task<ArchiveImportResult> ImportCoreAsync(
        string archivePath,
        GameProfile? game,
        Func<FomodInstallerService, CancellationToken, Task<IReadOnlySet<string>?>>? chooseFomod,
        CancellationToken ct)
'@
  if(-not $imp.Contains($sig)){throw 'IMPORTER_SIGNATURE_ANCHOR_NOT_FOUND'}
  $imp=$imp.Replace($sig,$replacement.TrimEnd())
  $publishOld='        await Task.Run(() => NormalizeSingleWrapper(staging), ct);'+[Environment]::NewLine+'        Directory.Move(staging, destination);'+[Environment]::NewLine+'        await catalog.RefreshFoldersAsync(ct);'
  $publishNew=@'
        await Task.Run(() => NormalizeSingleWrapper(staging), ct);
        try
        {
            if (FomodInstallerService.HasInstaller(staging))
            {
                if (game is null || chooseFomod is null)
                    throw new InvalidDataException("This archive uses a FOMOD installer and requires interactive option selection.");
                var installer = new FomodInstallerService(staging);
                var selected = await chooseFomod(installer, ct);
                if (selected is null) throw new OperationCanceledException("FOMOD installer cancelled.", ct);
                await installer.InstallAsync(selected, game, destination, ct);
            }
            else
            {
                Directory.Move(staging, destination);
            }
        }
        finally
        {
            if (Directory.Exists(staging)) Directory.Delete(staging, true);
        }
        await catalog.RefreshFoldersAsync(ct);
'@
  if(-not $imp.Contains($publishOld)){throw 'IMPORTER_PUBLISH_ANCHOR_NOT_FOUND'}
  $imp=$imp.Replace($publishOld,$publishNew.TrimEnd())
  [IO.File]::WriteAllText($importerPath,$imp,[Text.UTF8Encoding]::new($false))
  git add -- $importerPath

  $importVm='src/MhwModManager.App/ViewModels/MainWindowViewModel.Import.cs'
  $importContent=@'
using System.Text.Json;
using System.Windows;
using CommunityToolkit.Mvvm.Input;
using Microsoft.Win32;
using MhwModManager.Automation;
using MhwModManager.Core;

namespace MhwModManager.App.ViewModels;

public sealed partial class MainWindowViewModel
{
    [RelayCommand]
    private async Task ImportArchive()
    {
        using var __mhwTrace = MasterDebugLog.BeginMethod();
        var dlg=new OpenFileDialog{Filter="Mod archives|*.zip;*.7z;*.rar|All files|*.*",Multiselect=false};
        if(dlg.ShowDialog()!=true)return;
        await RunBusy("archive.import","Inspecting archive","Checking paths and extracting to a quarantined staging folder…",true,async ct=>
        {
            var imported=await s.Importer.ImportAsync(
                dlg.FileName,
                s.Paths.Game,
                async (installer,token)=>
                {
                    FomodSelection? saved=null;
                    var savedJson=await s.Database.GetSettingAsync("fomod.selection."+installer.ConfigSha256,token);
                    if(!string.IsNullOrWhiteSpace(savedJson))
                    {
                        try{saved=JsonSerializer.Deserialize<FomodSelection>(savedJson);}
                        catch(JsonException){saved=null;}
                    }

                    IReadOnlySet<string>? selected=null;
                    await Application.Current.Dispatcher.InvokeAsync(()=>
                    {
                        var chooser=new MhwModManager.App.FomodInstallerWindow(installer,s.Paths.Game,saved?.SelectedOptions)
                        {
                            Owner=Application.Current.MainWindow
                        };
                        if(chooser.ShowDialog()==true)
                            selected=chooser.SelectedOptions.ToHashSet(StringComparer.Ordinal);
                    });
                    if(selected is null)return null;
                    await s.Database.SetSettingAsync(
                        "fomod.selection."+installer.ConfigSha256,
                        JsonSerializer.Serialize(installer.Remember(selected)),
                        token);
                    return selected;
                },
                ct);
            await metadataGate.WaitAsync(ct);
            try{await s.Nexus.RefreshAsync(ct);}
            finally{metadataGate.Release();}
            await ReloadMods(ct);
            StatusText=$"Imported '{imported.DisplayName}'. It is OFF until you stage it.";
        });
    }
}
'@
  [IO.File]::WriteAllText($importVm,$importContent.TrimStart(),[Text.UTF8Encoding]::new($false))
  git add -- $importVm

  $u=@(git diff --name-only --diff-filter=U)
  if($u.Count -gt 0){throw ('UNRESOLVED_CONFLICTS:'+($u -join ','))}
  git diff --cached --check
  if($LASTEXITCODE -ne 0){throw 'DIFF_CHECK_FAILED'}

  Write-Output '=== STAGED_FILES ==='
  git diff --cached --name-status

  dotnet build MhwModManager.sln -c Release -m:1 -warnaserror
  if($LASTEXITCODE -ne 0){throw 'RELEASE_BUILD_FAILED'}
  dotnet test MhwModManager.sln -c Release --no-build
  if($LASTEXITCODE -ne 0){throw 'RELEASE_TEST_FAILED'}

  git commit -m 'Integrate complete mod workflows on current main'
  if($LASTEXITCODE -ne 0){throw 'MERGE_COMMIT_FAILED'}
  $head=(git rev-parse HEAD).Trim()
  git fetch origin
  $now=(git rev-parse origin/main).Trim()
  if($now -ne $base){throw ('MAIN_MOVED_AFTER_TESTS:'+ $base +'->'+$now)}
  git push -u origin $branch
  if($LASTEXITCODE -ne 0){throw 'PUSH_BRANCH_FAILED'}
  [pscustomobject]@{status='ready';base=$base;head=$head;branch=$branch;legacy=(git rev-parse HEAD^2).Trim()} | ConvertTo-Json -Compress
} finally { Pop-Location }
